mapper.select:
select count(*)
from sys_user
where deleted = 0
  and create_time >= #{from}
  and create_time < #{to}

select count(*)
from chat_session
where deleted = 0
  and create_time >= #{from}
  and create_time < #{to}

select date_format(start_time, '%Y-%m-%d') as groupKey,
       date_format(start_time, '%Y-%m-%d') as groupName,

from ai_call_log
where start_time >= #{from}
  and start_time < #{to}
group by date_format(start_time, '%Y-%m-%d')
order by groupKey
limit #{offset}, #{size}

select cast(model_id as char) as groupKey,
       coalesce(model_code, cast(model_id as char)) as groupName,

from ai_call_log
where start_time >= #{from}
  and start_time < #{to}
group by model_id, model_code
order by totalTokens desc, groupKey
limit #{offset}, #{size}

select cast(provider_id as char) as groupKey,
       coalesce(provider_name, cast(provider_id as char)) as groupName,

from ai_call_log
where start_time >= #{from}
  and start_time < #{to}
group by provider_id, provider_name
order by totalTokens desc, groupKey
limit #{offset}, #{size}
